#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""AArch64 static analysis helper: xref finder for strings & functions."""
import sys, struct
from elftools.elf.elffile import ELFFile
from elftools.elf.sections import SymbolTableSection
from capstone import Cs, CS_ARCH_ARM64, CS_MODE_ARM, CS_OP_IMM, CS_OP_MEM

class Bin:
    def __init__(self, path):
        self.f = open(path, 'rb')
        self.e = ELFFile(self.f)
        self.path = path
        self.text = self.e.get_section_by_name('.text')
        self.text_data = self.text.data()
        self.text_addr = self.text['sh_addr']
        self.md = Cs(CS_ARCH_ARM64, CS_MODE_ARM)
        self.md.detail = True
        # symbols
        self.syms = {}
        for sec in self.e.iter_sections():
            if isinstance(sec, SymbolTableSection):
                for s in sec.iter_symbols():
                    if s.name and s['st_value']:
                        self.syms.setdefault(s['st_value'], s.name)
                        self.syms.setdefault(s.name, s['st_value'])
        # PLT stubs: find via .plt section + rela.plt mapping
        self.plt = {}  # name -> plt addr
        pltsec = self.e.get_section_by_name('.plt')
        gotplt = self.e.get_section_by_name('.rela.plt')
        if pltsec and gotplt:
            symtab = self.e.get_section(gotplt['sh_link'])
            relocs = list(gotplt.iter_relocations())
            # heuristic: stub i at plt_base + 0x20 + i*0x10 (aarch64)
            base = pltsec['sh_addr']
            # find actual stub size by disassembling; assume 0x20 header + 0x10 each
            for i, r in enumerate(relocs):
                sym = symtab.get_symbol(r['r_info_sym'])
                self.plt[sym.name] = base + 0x20 + i * 0x10

    def read_cstr(self, off):
        self.f.seek(off)
        out = b''
        while True:
            c = self.f.read(1)
            if not c or c == b'\x00':
                break
            out += c
        return out.decode('latin-1', 'replace')

    def addr_to_off(self, addr):
        for seg in self.e.iter_segments():
            if seg['p_type'] == 'PT_LOAD' and seg['p_vaddr'] <= addr < seg['p_vaddr'] + seg['p_filesz']:
                return addr - seg['p_vaddr'] + seg['p_offset']
        return None

    def disas(self, addr, size):
        off = self.addr_to_off(addr)
        if off is None: return []
        self.f.seek(off)
        code = self.f.read(size)
        return list(self.md.disasm(code, addr))

    def func_of(self, addr):
        best = None
        for sec in self.e.iter_sections():
            if isinstance(sec, SymbolTableSection):
                for s in sec.iter_symbols():
                    if s['st_info']['type'] == 'STT_FUNC' and s['st_value'] <= addr < s['st_value'] + max(s['st_size'],1):
                        if best is None or s['st_value'] > best[0]:
                            best = (s['st_value'], s.name)
        return best

def find_bl_xrefs(b, target):
    """scan .text for bl target"""
    hits = []
    data = b.text_data
    base = b.text_addr
    for i in range(0, len(data), 4):
        w = struct.unpack_from('<I', data, i)[0]
        if (w >> 26) & 0x3f == 0x25:  # BL
            imm = w & 0x3ffffff
            if imm & 0x2000000: imm -= 0x4000000
            tgt = base + i + (imm << 2)
            if tgt == target:
                hits.append(base + i)
    return hits

def find_adrp_add_xrefs(b, addr):
    """scan .text for adrp+add pairs referencing addr (data)"""
    hits = []
    data = b.text_data
    base = b.text_addr
    page = addr & ~0xfff
    loval = addr & 0xfff
    for i in range(0, len(data), 4):
        w = struct.unpack_from('<I', data, i)[0]
        if (w & 0x9f000000) == 0x90000000:  # ADRP
            immlo = (w >> 29) & 3
            immhi = (w >> 5) & 0x7ffff
            imm = (immhi << 2) | immlo
            if imm & (1 << 20): imm -= (1 << 21)
            rd = w & 31
            pc = base + i
            tgt = (pc & ~0xfff) + (imm << 12)
            if tgt == page:
                # look ahead for ADD rd, rd, #loval within next 8 instrs
                for j in range(4, 40, 4):
                    if i + j + 4 > len(data): break
                    w2 = struct.unpack_from('<I', data, i + j)[0]
                    if (w2 & 0xff800000) == 0x91000000:  # ADD imm
                        imm12 = (w2 >> 10) & 0xfff
                        sh = (w2 >> 22) & 3
                        rd2 = w2 & 31
                        rn2 = (w2 >> 5) & 31
                        if rn2 == rd and ((imm12 << (12 if sh == 1 else 0)) == loval):
                            hits.append((pc, rd2))
                            break
                        if rd2 == rd and rn2 != rd:
                            break
    return hits

def string_at(b, addr):
    off = b.addr_to_off(addr)
    if off is None: return None
    return b.read_cstr(off)

def all_strings(b, minlen=4):
    import re
    data = open(b.path,'rb').read()
    out = []
    for m in re.finditer(rb'[\x20-\x7e]{%d,}' % minlen, data):
        out.append((b.addr_to_off_rev(m.start()) if hasattr(b,'addr_to_off_rev') else None, m.start(), m.group().decode('latin-1')))
    return out

if __name__ == '__main__':
    b = Bin(sys.argv[1])
    mode = sys.argv[2]
    if mode == 'bl':
        # bl xrefs to imported function name
        name = sys.argv[3]
        tgt = b.plt.get(name)
        print('plt', name, hex(tgt) if tgt else None)
        if tgt:
            for h in find_bl_xrefs(b, tgt):
                fn = b.func_of(h)
                print(hex(h), 'in', fn)
    elif mode == 'str':
        # xrefs to a string by offset (file offset)
        off = int(sys.argv[3], 16)
        # convert to vaddr
        addr = None
        for seg in b.e.iter_segments():
            if seg['p_type'] == 'PT_LOAD' and seg['p_offset'] <= off < seg['p_offset'] + seg['p_filesz']:
                addr = off - seg['p_offset'] + seg['p_vaddr']
        print('string vaddr', hex(addr) if addr else None, repr(b.read_cstr(off)))
        if addr:
            for pc, rd in find_adrp_add_xrefs(b, addr):
                fn = b.func_of(pc)
                print(hex(pc), 'reg x%d' % rd, 'in', fn)
    elif mode == 'disas':
        addr = int(sys.argv[3], 16)
        size = int(sys.argv[4], 16) if len(sys.argv) > 4 else 0x200
        for ins in b.disas(addr, size):
            print('%x: %s %s' % (ins.address, ins.mnemonic, ins.op_str))

